import { posix } from "node:path";
import type {
	Catalog,
	OperationContract,
	SelectedOperation,
	TypeUse,
} from "./contracts.ts";

const header =
	"// Generated by src/script/generate-sdk.ts. Edit backend contracts, then regenerate.\n";
const quote = JSON.stringify;
const compare = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

/** Render only selected, included operations. Unsupported contracts fail explicitly. */
export function renderSDK(catalog: Catalog): Map<string, string> {
	const files = new Map<string, string>();
	const pixels: SelectedOperation[] = [];
	const restGroups = new Map<string, SelectedOperation[]>();
	const sources = new Set<string>();
	for (const selected of [...catalog.operations].sort((a, b) =>
		compare(a.contract.source, b.contract.source),
	)) {
		const op = selected.contract;
		if (sources.has(op.source))
			throw new Error(`Duplicate operation: ${op.source}`);
		sources.add(op.source);
		if (op.kind === "REST") {
			const prefix = selected.applicationPath;
			if (!prefix || !/^\/[a-z][a-z0-9-]*$/.test(prefix))
				throw new Error(`Unsupported application path: ${prefix}`);
			if (!restGroups.has(prefix.slice(1)))
				restGroups.set(prefix.slice(1), []);
		}
		if (op.policy.ignoreReasons.length) continue;
		if (op.diagnostics.length) {
			throw new Error(
				`${op.source}: resolve contract diagnostics before generation: ${op.diagnostics.map((d) => d.message).join("; ")}`,
			);
		}
		if (!op.description.trim() || !op.outputs.length)
			throw new Error(`Incomplete contract: ${op.source}`);
		if (op.inputs.some((input) => input.requirement === "UNKNOWN"))
			throw new Error(`Unresolved requiredness: ${op.source}`);
		if (op.kind === "PIXEL") pixels.push(selected);
		else {
			const prefix = selected.applicationPath;
			if (!prefix || !/^\/[a-z][a-z0-9-]*$/.test(prefix))
				throw new Error(`Unsupported application path: ${prefix}`);
			const group = prefix.slice(1);
			const entries = restGroups.get(group) ?? [];
			entries.push(selected);
			restGroups.set(group, entries);
		}
	}
	for (const [group, operations] of restGroups) {
		const resource = `libs/sdk/src/api/${group}/${group}.ts`;
		// An ignored group's empty module preserves its curated package entry.
		if (!operations.length) {
			files.set(resource, `${header}\nexport {};\n`);
			continue;
		}
		const names = new Set<string>();
		const definitions = operations.map((selected) =>
			renderREST(selected, names),
		);
		files.set(
			resource,
			`${header}\nimport type { RequestOptions } from "../../lib/api-types";\nimport { get } from "../../utility/http";\nimport { path } from "../../utility/url";\n\n${definitions.join("\n")}`,
		);
	}
	const names = new Set<string>();
	const pixelEntries = pixels
		.sort((a, b) => compare(a.name, b.name))
		.map((selected) => {
			identifier(selected.name);
			if (names.has(selected.name))
				throw new Error(`Duplicate Pixel name: ${selected.name}`);
			names.add(selected.name);
			const op = selected.contract;
			const types = typeRenderer(op, selected.name);
			if (op.outputs.length !== 1 || op.outputs[0].status !== -1)
				throw new Error(`Expected one Pixel output: ${op.source}`);
			const parameters = pixelParameters(op, types.type);
			const output = types.type(op.outputs[0].type);
			return {
				definitions: types.definitions(),
				entry: `${doc(operationDocs(op))}\n${quote(selected.name)}: {\nparameters: ${parameters};\n${doc([op.outputs[0].description, ...typeDocs(op.outputs[0].type)])}\noutput: ${output};\ncanOmitParameters: ${op.invocation?.canOmitParameters};\n};`,
			};
		});
	files.set(
		"libs/sdk/src/lib/reactors/catalog.ts",
		`${header}\n${pixels.some((p) => p.contract.inputs.length) ? 'import type { RawPixel } from "../raw-pixel";\n\ntype PixelArgument<T> = T | RawPixel;\n' : ""}\n${pixelEntries.map((p) => p.definitions).join("\n")}\n/** Backend-declared input and successful output types for the selected reactors. */\nexport interface ReactorCatalog {\n${pixelEntries.map((p) => p.entry).join("\n")}\n}\n`,
	);
	files.set(
		"libs/sdk/src/lib/reactors/inventory.ts",
		`${header}\nexport const reactorNames = ${quote([...names])} as const;\n`,
	);
	return new Map([...files].sort(([a], [b]) => compare(a, b)));
}

/** Keep source provenance and independent policies on the generated declaration. */
function operationDocs(op: OperationContract): string[] {
	const lines = [op.description, `@source ${op.source}`];
	if (op.policy.internalReasons.length)
		lines.push(`@remarks Internal: ${op.policy.internalReasons.join(" ")}`);
	if (op.deprecation.deprecated) {
		lines.push(
			`@deprecated ${op.deprecation.reason || "Deprecated by the backend."} ${op.deprecation.replacement ? `Use ${op.deprecation.replacement}.` : ""} ${op.deprecation.forRemoval ? "Scheduled for removal." : ""}`,
		);
		if (op.deprecation.since) lines.push(`@since ${op.deprecation.since}`);
	}
	return lines;
}

function doc(lines: string[]): string {
	return `/**\n${lines
		.filter(Boolean)
		.flatMap((line) => line.replaceAll("*/", "* / ").split(/\r?\n/))
		.map((line) => ` * ${line}`)
		.join("\n")}\n */`;
}

function identifier(value: string): void {
	if (
		!/^[A-Za-z_$][\w$]*$/.test(value) ||
		new Set([
			"default",
			"class",
			"function",
			"const",
			"let",
			"var",
			"import",
			"export",
			"return",
			"delete",
			"new",
			"null",
			"true",
			"false",
		]).has(value)
	) {
		throw new Error(`Unsupported generated identifier: ${value}`);
	}
}

/** Definitions use opaque graph IDs; only the TypeScript renderer assigns names. */
function typeRenderer(
	op: OperationContract,
	prefix: string,
): {
	type: (value: TypeUse) => string;
	definitions: () => string;
} {
	const references = new Map(
		Object.keys(op.definitions)
			.sort(compare)
			.map((id, index) => [id, `${prefix}Type${index + 1}`]),
	);
	function type(value: TypeUse): string {
		if (value.knowledge === "UNVERIFIED")
			throw new Error(`${op.source}: unverified type: ${value.reason}`);
		if (value.knowledge === "DYNAMIC" && !value.reason.trim())
			throw new Error(`${op.source}: dynamic type needs a reason`);
		const shape = value.shape;
		let result: string;
		switch (shape.type) {
			case "scalar":
				if (shape.values.length && shape.kind !== "STRING")
					throw new Error("Only string enum values are supported");
				result = shape.values.length
					? [...shape.values]
							.sort(compare)
							.map((value) => quote(value))
							.join(" | ")
					: shape.kind === "STRING"
						? "string"
						: shape.kind === "BOOLEAN"
							? "boolean"
							: "number";
				break;
			case "sequence":
				result = `Array<${type(shape.element)}>`;
				break;
			case "dictionary":
				result = `Record<string, ${type(shape.value)}>`;
				break;
			case "union":
				if (!shape.alternatives.length)
					throw new Error("Empty contract union");
				result = shape.alternatives.map(type).join(" | ");
				break;
			case "reference": {
				const reference = references.get(shape.id);
				if (!reference)
					throw new Error(`Unresolved type reference: ${shape.id}`);
				result = reference;
				break;
			}
			case "unknown":
				if (value.knowledge !== "DYNAMIC")
					throw new Error(
						`${op.source}: unknown type must be explicitly dynamic`,
					);
				result = "unknown";
				break;
			case "empty":
				result = "void";
				break;
		}
		return value.nullable ? `${result} | null` : result;
	}
	return {
		type,
		definitions: () =>
			[...references]
				.map(([id, name]) => {
					const definition = op.definitions[id];
					if (definition.id !== id)
						throw new Error(`Mismatched type definition: ${id}`);
					const seen = new Set<string>();
					const fields = [...definition.properties]
						.sort((a, b) => compare(a.name, b.name))
						.map((property) => {
							if (seen.has(property.name))
								throw new Error(
									`Duplicate wire field: ${property.name}`,
								);
							seen.add(property.name);
							return `${doc(typeDocs(property.type))}\n${quote(property.name)}${property.required ? "" : "?"}: ${type(property.type)};`;
						});
					return `interface ${name} {\n${fields.join("\n")}\n}\n`;
				})
				.join("\n"),
	};
}

function typeDocs(type: TypeUse): string[] {
	return [
		type.description,
		type.format ? `@remarks Wire format: ${type.format}.` : "",
		type.reason ? `@remarks ${type.knowledge}: ${type.reason}` : "",
		type.shape.type === "scalar" && type.shape.kind === "INTEGER"
			? "@remarks Integer on the wire; JavaScript numbers must stay within their safe precision."
			: "",
	];
}

function pixelParameters(
	op: OperationContract,
	renderType: (value: TypeUse) => string,
): string {
	const invocation = op.invocation;
	if (!invocation) throw new Error(`Missing @Invocation: ${op.source}`);
	const inputs = new Map(op.inputs.map((input) => [input.name, input]));
	if (inputs.size !== op.inputs.length)
		throw new Error(`Duplicate Pixel input: ${op.source}`);
	const named: string[] = [];
	const wireNames = new Set<string>();
	for (const input of op.inputs) {
		if (input.binding !== "NOUN" || input.encoding !== "DEFAULT")
			throw new Error(`Unsupported Pixel binding: ${input.name}`);
		const names = [input.name, ...input.aliases];
		for (const name of names) {
			if (
				wireNames.has(name) ||
				!/^[A-Za-z_][A-Za-z0-9_]*$/.test(name) ||
				[
					"null",
					"true",
					"false",
					"TRUE",
					"FALSE",
					"META",
					"AND",
					"OR",
				].includes(name)
			)
				throw new Error(
					`Conflicting or unsupported Pixel input: ${name}`,
				);
			wireNames.add(name);
		}
		const field = (name: string, required: boolean): string =>
			`${doc([input.description, ...typeDocs(input.type)])}\n${quote(name)}${required ? "" : "?"}: PixelArgument<${renderType(input.type)}>;`;
		named.push(
			input.requirement === "REQUIRED" && names.length > 1
				? `(${names.map((required) => `{ ${names.map((name) => field(name, name === required)).join("\n")} }`).join(" | ")})`
				: `{ ${names.map((name) => field(name, input.requirement === "REQUIRED")).join("\n")} }`,
		);
	}
	const namedType = named.length
		? named.join(" & ")
		: "Record<string, never>";
	if (invocation.mode === "NAMED") return namedType;
	if (
		new Set(invocation.order).size !== op.inputs.length ||
		invocation.order.length !== op.inputs.length ||
		invocation.order.some((name) => !inputs.has(name))
	)
		throw new Error(`Incomplete positional order: ${op.source}`);
	let optionalSeen = false;
	const positional = invocation.order.map((name, index) => {
		const input = inputs.get(name);
		if (!input) throw new Error(`Unknown ordered input: ${name}`);
		if (name === invocation.variadic) {
			if (index !== invocation.order.length - 1)
				throw new Error("Variadic input must be last");
			const value =
				input.type.shape.type === "sequence"
					? input.type.shape.element
					: input.type;
			const required =
				input.requirement === "REQUIRED"
					? `PixelArgument<${renderType(value)}>, `
					: "";
			return `${required}...Array<PixelArgument<${renderType(value)}>>`;
		}
		if (optionalSeen && input.requirement === "REQUIRED")
			throw new Error(
				"Required positional input follows an optional input",
			);
		optionalSeen ||= input.requirement === "OPTIONAL";
		return `PixelArgument<${renderType(input.type)}>${input.requirement === "OPTIONAL" ? "?" : ""}`;
	});
	if (invocation.variadic && !inputs.has(invocation.variadic))
		throw new Error("Unknown variadic input");
	const positionalType = `[${positional.join(", ")}]`;
	return invocation.mode === "POSITIONAL"
		? positionalType
		: `(${namedType}) | ${positionalType}`;
}

/** Initial REST support: JSON GET endpoints with scalar path and query bindings. */
function renderREST(selected: SelectedOperation, names: Set<string>): string {
	const op = selected.contract;
	const rest = op.rest;
	if (!rest || rest.method !== "GET")
		throw new Error(`${op.source}: REST generation currently supports GET`);
	const route = `${selected.applicationPath}/${rest.path}`.replace(
		/\/{2,}/g,
		"/",
	);
	const last = route.split("/").filter(Boolean).at(-1) ?? selected.name;
	const name = /^[a-zA-Z_$][\w$]*$/.test(last) ? last : selected.name;
	identifier(name);
	if (names.has(name)) throw new Error(`Duplicate REST export: ${name}`);
	names.add(name);
	const typeName = name[0].toUpperCase() + name.slice(1);
	const types = typeRenderer(op, typeName);
	const statuses = new Set<number>();
	for (const output of op.outputs) {
		const media = output.mediaType ? [output.mediaType] : rest.produces;
		if (
			!media.length ||
			media.some((value) => value !== "application/json")
		)
			throw new Error(
				`${op.source}: REST generation requires explicit application/json responses`,
			);
		if (
			output.status < 100 ||
			output.status > 599 ||
			statuses.has(output.status)
		)
			throw new Error(
				`${op.source}: missing, conflicting, or unsupported HTTP status`,
			);
		statuses.add(output.status);
	}
	const success = [...statuses]
		.filter((status) => status >= 200 && status < 300)
		.sort((a, b) => a - b);
	if (!success.length)
		throw new Error(`${op.source}: no successful HTTP response declared`);
	const seen = new Set<string>();
	for (const input of op.inputs) {
		if (seen.has(input.name))
			throw new Error(`Duplicate REST input: ${input.name}`);
		seen.add(input.name);
		const shape = input.type.shape;
		const scalar = shape.type === "scalar";
		const scalarList =
			shape.type === "sequence" &&
			shape.element.shape.type === "scalar" &&
			!shape.element.nullable;
		if (
			!["PATH", "QUERY"].includes(input.binding) ||
			!["DEFAULT", "REPEATED"].includes(input.encoding) ||
			input.aliases.length ||
			(!scalar && !scalarList) ||
			input.type.nullable
		)
			throw new Error(
				`${op.source}: unsupported REST input ${input.name}; add a binding adapter before generating it`,
			);
		if (
			input.binding === "PATH" &&
			(!scalar ||
				shape.kind === "BOOLEAN" ||
				input.requirement !== "REQUIRED")
		)
			throw new Error(
				`Path input must be a required string or number: ${input.name}`,
			);
	}
	const pathNames = [...route.matchAll(/\{([^{}]+)\}/g)].map(
		(match) => match[1],
	);
	if (
		pathNames.some(
			(name) =>
				!op.inputs.some(
					(input) => input.binding === "PATH" && input.name === name,
				),
		) ||
		op.inputs.some(
			(input) =>
				input.binding === "PATH" && !pathNames.includes(input.name),
		)
	)
		throw new Error(`${op.source}: path placeholders and inputs disagree`);
	const routeParts = route
		.split(/(\{[^{}]+\})/g)
		.map((part) =>
			part.startsWith("{")
				? `\${params[${quote(part.slice(1, -1))}]}`
				: part
						.replaceAll("\\", "\\\\")
						.replaceAll("`", "\\`")
						.replaceAll("${", "\\${"),
		);
	const params = op.inputs.length
		? `{\n${op.inputs.map((input) => `${doc([input.description, ...typeDocs(input.type), input.defaultValue === null ? "" : `@defaultValue ${input.defaultValue}`])}\n${quote(input.name)}${input.requirement === "REQUIRED" ? "" : "?"}: ${types.type(input.type)};`).join("\n")}\n}`
		: "Record<string, never>";
	const query = op.inputs.filter((input) => input.binding === "QUERY");
	const queryValue = query.length
		? `{ ${query.map((input) => `${quote(input.name)}: params[${quote(input.name)}]`).join(", ")} }`
		: "undefined";
	const responses = op.outputs
		.map(
			(output) =>
				`${doc([output.description])}\n${output.status}: ${types.type(output.type)};`,
		)
		.join("\n");
	const responseType = `${typeName}Responses[${success.join(" | ")}]`;
	const comments = operationDocs(op).concat(
		`@endpoint GET ${route}`,
		"@param params - Declared backend inputs.",
		"@param options - Request headers and cancellation signal.",
		...op.outputs.map((output) =>
			output.status >= 200 && output.status < 300
				? `@returns ${output.description}`
				: `@throws {ApiError} HTTP ${output.status}: ${output.description}`,
		),
	);
	return `${types.definitions()}\n/** HTTP status to serialized body, including error responses. */\nexport interface ${typeName}Responses {\n${responses}\n}\n\n${doc(comments)}\nexport function ${name}(params: ${params}${op.inputs.every((input) => input.requirement === "OPTIONAL") ? " = {}" : ""}, options?: RequestOptions): Promise<${responseType}> {\n${op.inputs.length ? "" : "void params;\n"}return get(path\`${routeParts.join("")}\`, ${queryValue}, options);\n}\n`;
}

/** Paths owned by this generator are deliberately limited to generated SDK files. */
export function isGeneratedPath(file: string): boolean {
	return (
		posix.normalize(file) === file &&
		(/^libs\/sdk\/src\/api\/[a-z][a-z0-9-]*\/[a-z][a-z0-9-]*\.ts$/.test(
			file,
		) ||
			[
				"libs/sdk/src/lib/reactors/catalog.ts",
				"libs/sdk/src/lib/reactors/inventory.ts",
			].includes(file))
	);
}
